import math

class Var:
    def __init__(self, value, inputs=()):
        self.value = value
        self.inputs = inputs
        self.grad = 0.0

    def __add__(self, other):
        other = other if isinstance(other, Var) else Var(other)
        return Var(self.value + other.value, ((self, 1.0), (other, 1.0)))

    def __mul__(self, other):
        other = other if isinstance(other, Var) else Var(other)
        return Var(self.value * other.value, ((self, other.value), (other, self.value)))

    __radd__ = __add__
    __rmul__ = __mul__

    def tanh(self):
        t = math.tanh(self.value)
        return Var(t, ((self, 1 - t * t),))

    def backward(self):
        order, seen = [], set()
        stack = [(self, False)]
        while stack:                       # iterative depth-first search
            v, done = stack.pop()
            if done:
                order.append(v)
                continue
            if id(v) in seen:
                continue
            seen.add(id(v))
            stack.append((v, True))
            for parent, _ in v.inputs:
                if id(parent) not in seen:
                    stack.append((parent, False))
        for v in order:
            v.grad = 0.0
        self.grad = 1.0
        for v in reversed(order):
            for parent, local in v.inputs:
                parent.grad += local * v.grad

exercises.solution:
Two parts: a topological sort, then one reverse sweep of the chain rule. An explicit stack avoids Python's recursion limit on long chains:

```python
def backward(self):
    order, seen = [], set()
    stack = [(self, False)]
    while stack:
        v, done = stack.pop()
        if done:
            order.append(v)                # all inputs already placed
            continue
        if id(v) in seen:
            continue
        seen.add(id(v))
        stack.append((v, True))            # come back after the inputs
        for parent, _ in v.inputs:
            if id(parent) not in seen:
                stack.append((parent, False))
    for v in order:
        v.grad = 0.0
    self.grad = 1.0
    for v in reversed(order):
        for parent, local in v.inputs:
            parent.grad += local * v.grad
```

The `+=` is the "sum over children" of the multivariable chain rule: in `a * a * a`, `a` appears as an input three times and collects three contributions, totalling $3a^2$. Each node and edge is processed a constant number of times, so `backward` costs time linear in the size of the graph — the same order as the forward pass.

